      case Some(container) =>
        val results = mutable.ListBuffer[Option[Token]]()
        for (item <- container.getAll) {
          var processed: Option[Token] = None
          val handlersIter = _handlers.iterator
          while (handlersIter.hasNext && processed.isEmpty) {
