    if (processed.nonEmpty) Some(processed) else None
  }

  def tokenize(text: String): List[Token] = {
    val words = text.trim.split("\\s+")
    val tokens = mutable.ListBuffer[Token]()

    for ((word, i) <- words.zipWithIndex) {
      processToken(word) match {
        case Some(processed) =>
          tokens += Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
        case None => // skip
